# P116: independently integrate transient ODE and compare with closed form.
def forced(wd,dt=.0001):
 m=2.;b=15.;k=350.;F=15.;beta=b/(2*m);wn=sqrt(k/m-beta*beta)
 den=(k-m*wd*wd)**2+(b*wd)**2;C=F*(k-m*wd*wd)/den;D=-F*b*wd/den
 def exact(t):return C*sin(wd*t)+D*cos(wd*t)+exp(-beta*t)*(-D*cos(wn*t)+(-C*wd-beta*D)/wn*sin(wn*t))
 def derivative(t,z):return (z[1],(F*sin(wd*t)-b*z[1]-k*z[0])/m)
 t=0.;x=0.;v=0.;pts=[(t,x,v)];maxerr=0
 for j in range(round(1/dt)):
  a=derivative(t,(x,v));bb=derivative(t+dt/2,(x+dt*a[0]/2,v+dt*a[1]/2));cc=derivative(t+dt/2,(x+dt*bb[0]/2,v+dt*bb[1]/2));d=derivative(t+dt,(x+dt*cc[0],v+dt*cc[1]));x+=dt*(a[0]+2*bb[0]+2*cc[0]+d[0])/6;v+=dt*(a[1]+2*bb[1]+2*cc[1]+d[1])/6;t=(j+1)*dt;pts.append((t,x,v));maxerr=max(maxerr,abs(x-exact(t)))
 extrema=[pts[j] for j in range(1,len(pts)) if pts[j-1][2]*pts[j][2]<0]
 last=extrema[-2:];A=(abs(last[0][1])+abs(last[1][1]))/2;T=2*(last[1][0]-last[0][0]);return dict(wd=wd,amplitude=A,period=T,angular=2*pi/T,maxExactError=maxerr,lastExtrema=last,steadyAmplitude=F/sqrt(den))
forcing=[forced(w) for w in [35,sqrt(175),20]]
parts=[]
for letter,r in zip('abc',forcing):
 parts += [n(f'{letter} · Near-end amplitude estimate',r['amplitude'],'m','Use half the peak-to-trough range of the last two extrema near the end of the first second.',r['amplitude']*.12),n(f'{letter} · Near-end period estimate',r['period'],'s','Twice the separation of the last opposite-sign extrema estimates the local period.',r['period']*.05),n(f'{letter} · Near-end angular-frequency estimate',r['angular'],'rad/s','Estimate angular frequency as2π divided by the measured local period.',r['angular']*.05)]
parts.append(c('Trajectory and relative response','Each curve starts with x=v=0; the near-resonant case(b) has the largest amplitude, and transient motion remains during the first second.',['All curves begin at their full steady-state amplitude.','Case(a), with the highest drive frequency, has the largest amplitude.'],'The RK4 solution satisfies2a+15ẋ+350x=15sin(ωdt) with zero initial displacement and velocity.'))
