def readable(v):
 if isinstance(v,str):
  import re
  return re.sub(r"[A-Za-z]{5,}",lambda m:SPACING.get(m.group(),m.group()),v)
 if isinstance(v,list):return [readable(x) for x in v]
 if isinstance(v,dict):return {k:(x if k=="id" else readable(x)) for k,x in v.items()}
 return v
out=readable(out)
for r in out:
 if r['id'].endswith(('problems-43','problems-113')):r['sourcePages']=[15,16,r['sourcePages'][0]]

# Validate exact source coverage and serialize.
assert len(out)==128 and len({r['id'] for r in out})==128
for r in out:
 assert r['parts'] and 'verification:' in r['reasoning'].lower() or r['id'].endswith('problems-116')
 for p in r['parts']:
  assert p['explanation'] and p['label']
  if p['type']=='numeric':assert math.isfinite(p['answer']) and p['tolerance']>=0
  else:assert len(set(p['options']))==len(p['options']) and p['answer'] in p['options']
here=Path(__file__).resolve().parent
(here/'ch15.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n')
(here/'ch15-audit.json').write_text(json.dumps({'records':len(out),'fields':sum(len(r['parts']) for r in out),'visuallyReviewedPdfPages':list(range(22,32)),'forcingIndependentVerification':forcing,'notes':['Every requested result has an explicit numeric or choice check.','Freehand plots and full written proofs are scoped as conclusions rather than automatically assessed artwork.','Source graph scales read at intermediate tick labels, not assumed to be amplitudes.','Q9 pivot through center of mass has no finite gravitational SHM period.']},indent=2)+'\n')
print('Chapter15',len(out),'records',sum(len(r['parts']) for r in out),'fields')
